/* Pure crossword generation and validation, independent of the UI. */
(function(root){
'use strict';
const norm=(s,e=true)=>String(s||'').trim().toUpperCase().replace(/\s/g,'').replace(e?/Ё/g:/$^/g,'Е');
function cells(w){return Array.from(w.answer,(char,i)=>({r:w.r+(w.dir==='v'?i:0),c:w.c+(w.dir==='h'?i:0),char}));}
function board(words){const b=new Map();for(const w of words)for(const q of cells(w)){let k=q.r+','+q.c;let v=b.get(k)||{...q,words:[]};v.words.push(w.id);b.set(k,v);}return b;}
function fits(w,placed,size=40){const b=board(placed);let cross=0;const coords=cells(w);if(coords.some(q=>q.r<0||q.c<0||q.r>=size||q.c>=size))return false;
const before=w.dir==='h'?[w.r,w.c-1]:[w.r-1,w.c],after=w.dir==='h'?[w.r,w.c+w.answer.length]:[w.r+w.answer.length,w.c];if(b.has(before.join(','))||b.has(after.join(',')))return false;
for(const q of coords){const old=b.get(q.r+','+q.c);if(old){if(old.char!==q.char||old.words.some(id=>placed.find(x=>x.id===id).dir===w.dir))return false;cross++;}else{const sides=w.dir==='h'?[[q.r-1,q.c],[q.r+1,q.c]]:[[q.r,q.c-1],[q.r,q.c+1]];if(sides.some(p=>b.has(p.join(','))))return false;}}
return placed.length===0||cross>0;}
function bounds(words){const cs=words.flatMap(cells);if(!cs.length)return {rows:10,cols:10,minR:0,minC:0};let rs=cs.map(q=>q.r),cc=cs.map(q=>q.c);return {rows:Math.max(...rs)-Math.min(...rs)+1,cols:Math.max(...cc)-Math.min(...cc)+1,minR:Math.min(...rs),minC:Math.min(...cc)};}
function number(words){const points=[...new Set(words.map(w=>w.r+','+w.c))].map(k=>k.split(',').map(Number)).sort((a,b)=>a[0]-b[0]||a[1]-b[1]);return words.map(w=>({...w,num:points.findIndex(q=>q[0]===w.r&&q[1]===w.c)+1}));}
function generate(input,size=22,seed=1){let n=seed;const rand=()=>{n=(n*1664525+1013904223)>>>0;return n/4294967296;};const source=input.map(w=>({...w,answer:norm(w.answer,false),j:rand()})).filter(w=>w.answer.length&&w.answer.length<=size).sort((a,b)=>b.answer.length-a.answer.length+(a.j-b.j)*8);let placed=[];
for(let pass=0;pass<3;pass++)for(const word of source){if(placed.some(w=>w.id===word.id))continue;let candidates=[];if(!placed.length)candidates.push({...word,r:Math.floor(size/2),c:Math.floor((size-word.answer.length)/2),dir:'h'});else for(const p of placed)for(let i=0;i<p.answer.length;i++)for(let j=0;j<word.answer.length;j++)if(p.answer[i]===word.answer[j]){const dir=p.dir==='h'?'v':'h';const r=p.r+(p.dir==='v'?i:0)-(dir==='v'?j:0),c=p.c+(p.dir==='h'?i:0)-(dir==='h'?j:0);const w={...word,r,c,dir};if(fits(w,placed,size))candidates.push(w);}
if(candidates.length){candidates.sort((a,b)=>{const ba=bounds([...placed,a]),bb=bounds([...placed,b]);return ba.rows*ba.cols-bb.rows*bb.cols;});placed.push(candidates[Math.floor(rand()*Math.min(3,candidates.length))]);}}
const bb=bounds(placed);placed=number(placed.map(({j,...w})=>({...w,r:w.r-bb.minR,c:w.c-bb.minC})));const b=board(placed);return {words:placed,rows:bb.rows,cols:bb.cols,crossings:[...b.values()].filter(c=>c.words.length>1).length,missing:input.filter(w=>!placed.some(p=>p.id===w.id)).map(w=>w.id)};}
function validate(input,layout,size=40){let errors=[];let seen=new Set();for(const w of input){if(!norm(w.answer)||!w.clue?.trim())errors.push('Заполните ответ и вопрос для каждого слова.');if(seen.has(norm(w.answer)))errors.push('Повторяется ответ «'+w.answer+'».');seen.add(norm(w.answer));if(norm(w.answer).length>size)errors.push('Слово «'+w.answer+'» длиннее сетки.');}for(const w of layout.words){for(const q of cells(w)){if(q.r<0||q.c<0||q.r>=size||q.c>=size)errors.push('Слово выходит за сетку.');}for(const p of layout.words.filter(p=>p.id!==w.id))for(const a of cells(w))for(const b of cells(p))if(a.r===b.r&&a.c===b.c&&(a.char!==b.char||w.dir===p.dir))errors.push('Конфликт слов в сетке.');}if(layout.missing?.length)errors.push('Не размещено слов: '+layout.missing.length+'. Выберите другую раскладку или измените список.');return [...new Set(errors)];}
const api={norm,cells,board,fits,bounds,number,generate,validate};root.Crossword=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
